function renderNotFound(slug) {
  return d("div", {
    style: {
      minHeight: "80vh",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      padding: "40px 20px",
      fontFamily: "Inter, sans-serif",
      backgroundColor: "#ffffff",
      textAlign: "center"
    }
  }, [
    d("div", {
      key: "badge",
      style: {
        fontSize: "13px",
        fontWeight: "600",
        textTransform: "uppercase",
        letterSpacing: "0.1em",
        color: "#666",
        backgroundColor: "#f5f5f5",
        padding: "6px 14px",
        borderRadius: "20px",
        marginBottom: "20px"
      }
    }, "404 • Product Not Found"),
    d("h1", {
      key: "title",
      style: {
        fontSize: "36px",
        fontWeight: "700",
        color: "#000000",
        margin: "0 0 12px",
        letterSpacing: "-0.02em"
      }
    }, "Sneaker Not Found"),
    d("p", {
      key: "desc",
      style: {
        fontSize: "16px",
        color: "#666666",
        maxWidth: "480px",
        lineHeight: "1.6",
        margin: "0 0 32px"
      }
    }, "We couldn't find a sneaker matching \"" + (slug || "this URL") + "\". The pair may have sold out, been archived, or the link may have a typo."),
    d("div", {
      key: "actions",
      style: {
        display: "flex",
        gap: "12px",
        flexWrap: "wrap",
        justifyContent: "center"
      }
    }, [
      d("a", {
        key: "catalog-btn",
        href: "/shoes",
        style: {
          display: "inline-block",
          backgroundColor: "#000000",
          color: "#ffffff",
          padding: "14px 28px",
          borderRadius: "12px",
          fontSize: "14px",
          fontWeight: "600",
          textDecoration: "none"
        }
      }, "Explore All Sneakers"),
      d("a", {
        key: "home-btn",
        href: "/",
        style: {
          display: "inline-block",
          backgroundColor: "#f5f5f5",
          color: "#000000",
          padding: "14px 28px",
          borderRadius: "12px",
          fontSize: "14px",
          fontWeight: "600",
          textDecoration: "none",
          border: "1px solid #e5e5e5"
        }
      }, "Return to Home")
    ])
  ]);
}

function renderError(err, onRetry) {
  return d("div", {
    style: {
      minHeight: "80vh",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      padding: "40px 20px",
      fontFamily: "Inter, sans-serif",
      backgroundColor: "#ffffff",
      textAlign: "center"
    }
  }, [
    d("div", {
      key: "badge",
      style: {
        fontSize: "13px",
        fontWeight: "600",
        textTransform: "uppercase",
        letterSpacing: "0.1em",
        color: "#d32f2f",
        backgroundColor: "#ffebee",
        padding: "6px 14px",
        borderRadius: "20px",
        marginBottom: "20px"
      }
    }, "Loading Error"),
    d("h1", {
      key: "title",
      style: {
        fontSize: "32px",
        fontWeight: "700",
        color: "#000000",
        margin: "0 0 12px"
      }
    }, "Unable to Load Sneaker"),
    d("p", {
      key: "desc",
      style: {
        fontSize: "16px",
        color: "#666666",
        maxWidth: "480px",
        lineHeight: "1.6",
        margin: "0 0 32px"
      }
    }, err && err.message ? err.message : "A temporary connection issue prevented sneaker details from loading. Please retry."),
    d("div", {
      key: "actions",
      style: {
        display: "flex",
        gap: "12px",
        justifyContent: "center"
      }
    }, [
      d("button", {
        key: "retry-btn",
        onClick: onRetry || (() => { if(typeof window !== "undefined") window.location.reload(); }),
        style: {
          cursor: "pointer",
          backgroundColor: "#000000",
          color: "#ffffff",
          padding: "14px 28px",
          borderRadius: "12px",
          fontSize: "14px",
          fontWeight: "600",
          border: "none"
        }
      }, "Retry Loading"),
      d("a", {
        key: "catalog-btn",
        href: "/shoes",
        style: {
          display: "inline-block",
          backgroundColor: "#f5f5f5",
          color: "#000000",
          padding: "14px 28px",
          borderRadius: "12px",
          fontSize: "14px",
          fontWeight: "600",
          textDecoration: "none",
          border: "1px solid #e5e5e5"
        }
      }, "Browse Catalog")
    ])
  ]);
}

